(ns hooks.gdal
  "clj-kondo hooks for the fns that clj-gdal makes from its fndefs.
   `c-names` holds the C names, because a hook runs in SCI and cannot read
   fndefs. bb kondo:fndefs writes the list."
  (:require [clj-kondo.hooks-api :as api]
            [hooks.native.generated :as gen]))

