(def ^:private fndefs-keys (zipmap c-names (repeat nil)))

(defn define-all-gdal-public-fns
  "Declare each fn that the macro makes, with no arity, because the hook
   has only the C names. The node also refers to gdal-call or dispatch-gdal,
   because clj-kondo otherwise reports that private fn as unused."
  [{:keys [lang]}]
  {:node (api/list-node
          [(api/token-node 'do)
           (gen/declare-node fndefs-keys gen/camel-name->clj-name)
           (api/token-node (if (= :cljs lang) 'dispatch-gdal 'gdal-call))])})
